const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function newCamera(battle=false){return {yaw:battle?-.65:-2.55,elevation:battle?.86:.68,zoom:1,panX:0,panZ:0,follow:'both',drag:'orbit',current:null};}
export function screenDirection(x,y,camera){return {x:Math.cos(camera.yaw)*x+Math.sin(camera.yaw)*y,y:-Math.sin(camera.yaw)*x+Math.cos(camera.yaw)*y};}
export function fittedSpan(machine,aspect,yaw,elevation,gap=1.65){const xs=machine.modules.map(m=>m.x-4),zs=machine.modules.map(m=>m.y-4),heights=machine.modules.map(m=>(m.z||0)*gap+1.7);const minX=Math.min(...xs)-.8,maxX=Math.max(...xs)+.8,minZ=Math.min(...zs)-.8,maxZ=Math.max(...zs)+.8,maxH=Math.max(...heights),center=[(minX+maxX)/2,maxH*.46,(minZ+maxZ)/2];let minU=Infinity,maxU=-Infinity,minV=Infinity,maxV=-Infinity;for(const x of [minX,maxX])for(const z of [minZ,maxZ])for(const h of [0,maxH]){const u=x*Math.cos(yaw)-z*Math.sin(yaw),v=-x*Math.sin(yaw)*Math.sin(elevation)+h*Math.cos(elevation)-z*Math.cos(yaw)*Math.sin(elevation);minU=Math.min(minU,u);maxU=Math.max(maxU,u);minV=Math.min(minV,v);maxV=Math.max(maxV,v);}return {center,span:Math.max(6,maxV-minV+1.8,(maxU-minU+1.8)/Math.max(.3,aspect))};}
export function bindCamera(canvas,camera,{change=()=>{},tap=()=>{},hover=()=>{}}={}){
 const points=new Map();let start=null,last=null,pinched=false,dragged=false,lastDistance=0;
 const position=e=>({x:e.clientX,y:e.clientY});
 const pan=(dx,dy)=>{const amount=(canvas.clientHeight||500)/camera.zoom;const d=screenDirection(dx,dy,camera);camera.panX-=d.x/amount*12;camera.panZ-=d.y/amount*12;if(canvas.id==='arena-canvas')camera.follow='free';};
 canvas.onpointerdown=e=>{if(![0,1,2].includes(e.button)&&e.pointerType==='mouse')return;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);points.set(e.pointerId,position(e));if(points.size===1){start=position(e);last=position(e);dragged=false;pinched=false;}else{pinched=true;const [a,b]=[...points.values()];lastDistance=Math.hypot(a.x-b.x,a.y-b.y);}e.preventDefault();};
 canvas.onpointermove=e=>{if(!points.has(e.pointerId)){if(e.pointerType==='mouse')hover(e);return;}const previous=points.get(e.pointerId);points.set(e.pointerId,position(e));if(points.size>=2){const [a,b]=[...points.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(lastDistance>0)camera.zoom=clamp(camera.zoom*d/lastDistance,.45,2.8);lastDistance=d;pan((e.clientX-previous.x)*.5,(e.clientY-previous.y)*.5);change();return;}if(pinched)return;if(Math.hypot(e.clientX-start.x,e.clientY-start.y)>6)dragged=true;if(!dragged)return;const dx=e.clientX-last.x,dy=e.clientY-last.y;if(e.buttons===2||e.buttons===4||e.shiftKey||camera.drag==='pan')pan(dx,dy);else{camera.yaw-=dx*.008;camera.elevation=clamp(camera.elevation+dy*.006,.28,1.48);}last=position(e);change();};
 canvas.onpointerup=e=>{if(!points.has(e.pointerId))return;points.delete(e.pointerId);if(!dragged&&!pinched)tap(e);if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(!points.size){start=null;last=null;lastDistance=0;}};
 canvas.onpointercancel=()=>{points.clear();start=null;last=null;};canvas.onpointerleave=()=>{if(!points.size)hover(null);};canvas.oncontextmenu=e=>e.preventDefault();canvas.addEventListener('wheel',e=>{e.preventDefault();camera.zoom=clamp(camera.zoom*Math.exp(-e.deltaY*.0015),.45,2.8);change();},{passive:false});
}
